 * Project: ESP32-Based Segmenya LED Bar Project
 * Description: This project utilizes an ESP32 microcontroller to control a series of Segmenya LEDs, creating a visually appealing LED bar pattern. The ESP32 will manage the individual LED states and synchronize them to form a distinct pattern using a Segmenya driver circuit.
 */
#include <Arduino.h>
#include <Adafruit_Sensor.h>
#include <DHT.h>

#define DHTPIN 4
#define DHTTYPE DHT22
#define LED_PIN 2
const float THRESHOLD_VAL = 30.0;

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 3000) { delay(10); }
  Serial.println(F("--- ESP32-Based Segmenya LED Bar Project Initialized ---"));
  pinMode(LED_PIN, OUTPUT); digitalWrite(LED_PIN, LOW);
  dht.begin();
}

void loop() {
  delay(2000);
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (isnan(t) || isnan(h)) { Serial.println(F("[ERROR] Failed reading DHT22")); return; }
  Serial.print(F("Temp: ")); Serial.print(t, 1); Serial.print(F(" C | Humidity: ")); Serial.print(h, 1); Serial.println(F(" %"));
  bool alarm = (t > THRESHOLD_VAL);
  digitalWrite(LED_PIN, alarm ? HIGH : LOW);
}

