/*
 * Auto-generated by CircuitForge AI (Deterministic Catalog Generator)
 * Project: Radar & Display Project - Basic IoT System
 * Description: This project will build a simple IoT system utilizing an ESP32 microcontroller, incorporating a radar sensor for distance measurement and an HC-SR04 ultrasonic distance sensor, all displayed on a 16x2 I2C character LCD. The system will provide a basic visual representation of the radar's output.
 */
#include <Arduino.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

#define TRIG_PIN 5
#define ECHO_PIN 18
const float THRESHOLD_VAL = 2.0;

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 3000) { delay(10); }
  Serial.println(F("--- Radar & Display Project - Basic IoT System Initialized ---"));
  pinMode(TRIG_PIN, OUTPUT); pinMode(ECHO_PIN, INPUT);
  lcd.init(); lcd.backlight();
  lcd.setCursor(0, 0); lcd.print(F("CircuitForge AI"));
}

void loop() {
  digitalWrite(TRIG_PIN, LOW); delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10); digitalWrite(TRIG_PIN, LOW);
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  float distanceCm = (duration > 0) ? (duration * 0.0343 / 2.0) : 999.0;
  Serial.print(F("Distance: ")); Serial.print(distanceCm, 1); Serial.println(F(" cm"));
  bool alarm = (distanceCm < THRESHOLD_VAL);
  delay(200);
  lcd.setCursor(0, 1);
  lcd.print(alarm ? F("STATUS: ACTIVE! ") : F("STATUS: OK      "));
  if (alarm) { Serial.println(F("[ALERT] Trigger condition active!")); }
}
